<?php
namespace Pterodactyl\Http\Controllers\Admin;
use Illuminate\Http\Request; use Illuminate\Support\Facades\Crypt; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Schema; use Pterodactyl\Http\Controllers\Controller; use Pterodactyl\Services\Nodexa\FlaxVpsClient;
class VpsHostingController extends Controller { public function index(){ $provider=Schema::hasTable('vps_providers')?DB::table('vps_providers')->first():null;$packages=Schema::hasColumn('billing_products','product_type')?DB::table('billing_products')->where('product_type','vps')->orderBy('sort_order')->get():collect();$services=Schema::hasTable('vps_services')?DB::table('vps_services')->orderByDesc('id')->limit(50)->get():collect();return view('admin.commerce.vps',compact('provider','packages','services'));} public function saveProvider(Request $r){$d=$r->validate(['endpoint'=>'required|url|max:255','api_key'=>'nullable|string|max:1000']);$old=DB::table('vps_providers')->first();$key=!empty($d['api_key'])?Crypt::encryptString($d['api_key']):($old->api_key??null);if(!$key)return back()->withErrors(['api_key'=>'API-nøgle er påkrævet første gang.']);$values=['name'=>'Flax Hosting','endpoint'=>rtrim($d['endpoint'],'/'),'api_key'=>$key,'active'=>true,'updated_at'=>now()];if($old)DB::table('vps_providers')->where('id',$old->id)->update($values);else DB::table('vps_providers')->insert($values+['created_at'=>now()]);return back()->with('success','Flax VPS API blev gemt sikkert.');} public function test(){try{$data=(new FlaxVpsClient())->servers();return back()->with('success','Forbindelsen til Flax virker. API returnerede '.count($data).' server(e).');}catch(\Throwable $e){return back()->withErrors(['flax'=>$e->getMessage()]);}} }
